 {"id":"ed28ecbf-7109-43a5-8ffb-eb4d658f2f77","agency_id":"b67bb03f-bcf1-419e-83a2-224964147e34","title":"Video 6","description":"&lt;p&gt;Could Ancient Humans Prevent Pregnancy?&lt;/p&gt;","status":"archived","client_id":null,"due_date":"2026-06-16T19:00:00+00:00","budget":34.00,"created_at":"2026-06-16T09:21:13.213159+00:00","updated_at":"2026-07-18T05:52:35.349141+00:00","editor_rate":10,"completed_at":null,"reference_links":null,"container_id":"a8baf896-777e-4bca-a451-b0bfe75bad7d","managed_client_id":"2015c089-44f4-4a3c-9ef0-d88d7a33202a"}, 
